package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		b, _ := strconv.ParseInt(strings.TrimSpace(scanner.Text()), 10, 64)
		counter := 0
		sqrt := math.Sqrt(float64(b))

		for i := int64(2); float64(i) < sqrt; i++ {
			if b%i == 0 {
				counter += 2
			}
		}

		if math.Mod(sqrt, 1) == 0 {
			counter++
		}

		if b == 1 {
			fmt.Println(1)
		} else {
			fmt.Println(counter + 2)
		}
	}
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var b int64
	fmt.Fscan(in, &b)

	counter := 0
	sqrt := math.Sqrt(float64(b))

	for i := int64(2); float64(i) < sqrt; i++ {
		if b%i == 0 {
			counter += 2
		}
	}

	if sqrt == math.Trunc(sqrt) {
		counter++
	}

	if b == 1 {
		fmt.Fprintln(out, 1)
	} else {
		fmt.Fprintln(out, counter+2)
	}
}

