const readline = require('readline');

const rl = readline.createInterface({
	input: process.stdin,
	output: process.stdout,
	terminal: false
});

rl.on('line', function(line){
	const b = parseInt(line);
	let counter = 0;
	const sqrt = Math.sqrt(b)
	for (let i = 2; i < sqrt; i++) {
		if (b % i === 0) { counter += 2; }
	}
	if (sqrt % 1 === 0) { counter++; }
	console.log(b === 1 ? 1 : counter + 2);
	rl.close();
});
